@dataclass(frozen=True, slots=True)
class _PrimarySourceProbe:
    """A bounded, non-executing classification of one immutable input."""

    source: SourceFile
    inspected: bool = False
    format: str = "unknown"
    executable_mode: bool = False
    elf_executable: bool = False
    elf_shared_object: bool = False


def _elf_has_interpreter(
    descriptor: int,
    size: int,
    header: bytes,
) -> bool:
    """Return whether a bounded, structurally valid ELF has ``PT_INTERP``."""

    if len(header) < 58 or header[4] not in {1, 2} or header[5] not in {1, 2}:
        return False
    byte_order = "<" if header[5] == 1 else ">"
    if header[4] == 1:
        if len(header) < 46:
            return False
        program_offset = struct.unpack_from(f"{byte_order}I", header, 28)[0]
        entry_size = struct.unpack_from(f"{byte_order}H", header, 42)[0]
        entry_count = struct.unpack_from(f"{byte_order}H", header, 44)[0]
    else:
        program_offset = struct.unpack_from(f"{byte_order}Q", header, 32)[0]
        entry_size = struct.unpack_from(f"{byte_order}H", header, 54)[0]
        entry_count = struct.unpack_from(f"{byte_order}H", header, 56)[0]
    table_size = entry_size * entry_count
    if (
        entry_size < 4
        or entry_count == 0
        or entry_count > 4096
        or table_size > 1024 * 1024
        or program_offset > size
        or table_size > size - program_offset
    ):
        return False
    table = os.pread(descriptor, table_size, program_offset)
    if len(table) != table_size:
        return False
    return any(
        struct.unpack_from(f"{byte_order}I", table, index * entry_size)[0] == 3
        for index in range(entry_count)
    )


def _classify_primary_source(
    source_root: Path,
    source: SourceFile,
) -> _PrimarySourceProbe:
    """Safely inspect input bytes without following links or running them."""

    try:
        normalized = normalize_locator(source.path)
    except SafeFileError:
        return _PrimarySourceProbe(source)
    directory_flags = os.O_RDONLY | os.O_CLOEXEC
    directory_flags |= getattr(os, "O_DIRECTORY", 0)
    directory_flags |= getattr(os, "O_NOFOLLOW", 0)
    file_flags = os.O_RDONLY | os.O_CLOEXEC | os.O_NONBLOCK
    file_flags |= getattr(os, "O_NOFOLLOW", 0)
    directory_descriptor: int | None = None
    file_descriptor: int | None = None
    try:
        directory_descriptor = os.open(source_root, directory_flags)
        parts = normalized.split("/")
        for component in parts[:-1]:
            next_descriptor = os.open(
                component,
                directory_flags,
                dir_fd=directory_descriptor,
            )
            os.close(directory_descriptor)
            directory_descriptor = next_descriptor
        file_descriptor = os.open(
            parts[-1],
            file_flags,
            dir_fd=directory_descriptor,
        )
        before = os.fstat(file_descriptor)
        if not stat.S_ISREG(before.st_mode) or before.st_size != source.size:
            return _PrimarySourceProbe(source)
        header = os.pread(file_descriptor, min(before.st_size, 64), 0)
        detected_format = "unknown"
        elf_executable = False
        elf_shared_object = False
        if header.startswith(b"\x7fELF") and len(header) >= 18:
            detected_format = "elf"
            byte_order = (
                "<" if header[5:6] == b"\x01" else ">"
                if header[5:6] == b"\x02"
                else None
            )
            if byte_order is not None:
                elf_type = struct.unpack_from(f"{byte_order}H", header, 16)[0]
                has_interpreter = (
                    elf_type == 3
                    and _elf_has_interpreter(
                        file_descriptor,
                        before.st_size,
                        header,
                    )
                )
                elf_executable = elf_type == 2 or has_interpreter
                elf_shared_object = elf_type == 3 and not has_interpreter
        elif header.startswith(b"MZ") and len(header) >= 64:
            pe_offset = struct.unpack_from("<I", header, 60)[0]
            if pe_offset <= before.st_size - 24 and pe_offset <= 16 * 1024**2:
                pe_header = os.pread(file_descriptor, 24, pe_offset)
                if len(pe_header) == 24 and pe_header.startswith(b"PE\0\0"):
                    characteristics = struct.unpack_from("<H", pe_header, 22)[0]
                    detected_format = (
                        "pe_executable"
                        if characteristics & 0x0002
                        and not characteristics & 0x2000
                        else "pe_library"
                    )
        elif header[:4] in {
            b"\x00asm",
            b"dex\n",
        }:
            detected_format = (
                "wasm" if header[:4] == b"\x00asm" else "dex"
            )
        elif header[:4] in {
            b"\xca\xfe\xba\xbe",
            b"\xce\xfa\xed\xfe",
            b"\xcf\xfa\xed\xfe",
            b"\xfe\xed\xfa\xce",
            b"\xfe\xed\xfa\xcf",
        }:
            detected_format = "mach_o"
        after = os.fstat(file_descriptor)
        stable_fields = (
            "st_dev",
            "st_ino",
            "st_mode",
            "st_size",
            "st_mtime_ns",
            "st_ctime_ns",
        )
        if any(
            getattr(before, field) != getattr(after, field)
            for field in stable_fields
        ):
            return _PrimarySourceProbe(source)
        return _PrimarySourceProbe(
            source=source,
            inspected=True,
            format=detected_format,
            executable_mode=bool(before.st_mode & 0o111),
            elf_executable=elf_executable,
            elf_shared_object=elf_shared_object,
        )
    except (OSError, OverflowError, struct.error, ValueError):
        return _PrimarySourceProbe(source)
    finally:
        if file_descriptor is not None:
            try:
                os.close(file_descriptor)
            except OSError:
                pass
        if directory_descriptor is not None:
            try:
                os.close(directory_descriptor)
            except OSError:
                pass


def _source_role_flags(path: str) -> tuple[bool, bool, bool, bool]:
    lowered = path.casefold()
    basename = PurePosixPath(lowered).name
    is_archive = any(
        lowered.endswith(suffix) for suffix in _PRIMARY_ARCHIVE_SUFFIXES
    )
    is_document = (
        any(lowered.endswith(suffix) for suffix in _PRIMARY_DOCUMENT_SUFFIXES)
        or basename
        in {
            "license",
            "license.txt",
            "readme",
            "readme.txt",
        }
    )
    is_library = bool(
        re.match(r"^lib[^/]*\.so(?:\.|$)", basename)
        or re.match(r"^ld(?:-|\.|64)", basename)
        or basename.endswith((".a", ".dll", ".dylib", ".o"))
    )
    has_primary_hint = any(
        token in re.split(r"[^a-z0-9]+", basename)
        for token in (
            "app",
            "binary",
            "chall",
            "challenge",
            "check",
            "checker",
            "main",
            "oracle",
            "server",
            "service",
            "task",
            "vuln",
        )
    )
    return is_archive, is_document, is_library, has_primary_hint


def _primary_source_score(category: str, probe: _PrimarySourceProbe) -> int:
    """Assign category-aware priority; path ordering remains the tie-breaker."""

    source = probe.source
    lowered = source.path.casefold()
    suffix = PurePosixPath(lowered).suffix
    basename = PurePosixPath(lowered).name
    is_archive, is_document, is_library, has_primary_hint = (
        _source_role_flags(lowered)
    )
    nonempty = 1 if source.size else 0
    if category in {"pwn", "reversing"}:
        if probe.elf_executable:
            score = 10_000
        elif probe.format == "pe_executable":
            score = 9_500
        elif probe.format in {"mach_o", "wasm", "dex"}:
            score = 8_500 if category == "reversing" else 6_000
        elif probe.elf_shared_object:
            score = (
                8_800
                if probe.executable_mode and not is_library
                else 4_000
            )
        elif probe.executable_mode and not is_library and not is_archive:
            score = 6_500
        elif suffix in _PRIMARY_SOURCE_SUFFIXES:
            score = 5_000
        elif is_archive:
            score = 3_500
        else:
            score = 2_500
        if is_library:
            score -= 1_500
        if is_document:
            score -= 2_000
    elif category == "crypto":
        if suffix == ".sage":
            score = 9_500
        elif suffix == ".py":
            score = 9_000
        elif suffix == ".ipynb":
            score = 8_500
        elif suffix in _PRIMARY_SOURCE_SUFFIXES:
            score = 7_500
        elif suffix in {".json", ".pem", ".pub", ".txt"}:
            score = 5_500
        elif is_archive:
            score = 4_500
        else:
            score = 4_000
        if any(token in basename for token in ("solution", "solve", "writeup")):
            score -= 3_000
        if is_document:
            score -= 2_000
    elif category == "web":
        if suffix in {".js", ".php", ".py", ".rb", ".ts"}:
            score = 8_000
        elif basename in {
            "composer.json",
            "go.mod",
            "package.json",
            "pom.xml",
            "requirements.txt",
        }:
            score = 7_500
        elif suffix in _PRIMARY_SOURCE_SUFFIXES:
            score = 7_000
        elif suffix in {".html", ".sql", ".vue"}:
            score = 6_500
        elif is_archive:
            score = 4_500
        else:
            score = 4_000
        if is_document:
            score -= 2_000
    elif category == "forensics":
        if suffix in {
            ".dd",
            ".dmp",
            ".e01",
            ".evtx",
            ".img",
            ".log",
            ".mbox",
            ".mem",
            ".pcap",
            ".pcapng",
            ".raw",
            ".vmdk",
        }:
            score = 9_000
        elif suffix in {
            ".avi",
            ".bmp",
            ".eml",
            ".gif",
            ".jpeg",
            ".jpg",
            ".mp3",
            ".mp4",
            ".png",
            ".wav",
        }:
            score = 8_000
        elif is_archive:
            score = 7_000
        else:
            score = 4_000
        if is_document:
            score -= 1_500
    else:
        if probe.format in {
            "dex",
            "elf",
            "mach_o",
            "pe_executable",
            "wasm",
        }:
            score = 8_000
        elif suffix in {
            ".avi",
            ".bmp",
            ".gif",
            ".jpeg",
            ".jpg",
            ".mp3",
            ".mp4",
            ".png",
            ".wav",
        }:
            score = 7_500
        elif is_archive:
            score = 7_000
        elif suffix in _PRIMARY_SOURCE_SUFFIXES:
            score = 6_500
        else:
            score = 5_000
        if is_document:
            score -= 2_000
    if has_primary_hint:
        score += 250
    return score + nonempty


def _select_adapter_primary_source(
    category: str,
    source_root: Path,
    sources: Sequence[SourceFile],
) -> SourceFile | None:
    """Choose one deterministic adapter seed without executing challenge input."""

    normalized_category = category.strip().casefold()
    if normalized_category in {"binary", "binary-exploitation"}:
        normalized_category = "pwn"
    elif normalized_category in {"re", "rev", "reverse"}:
        normalized_category = "reversing"
    elif normalized_category in {"cryptography"}:
        normalized_category = "crypto"
    elif normalized_category in {"dfir", "forensic"}:
        normalized_category = "forensics"
    elif normalized_category == "web-security":
        normalized_category = "web"
    probes = [
        (
            _classify_primary_source(source_root, source)
            if normalized_category in {"pwn", "reversing"}
            else _PrimarySourceProbe(source)
        )
        for source in sources
    ]
    if normalized_category in {"pwn", "reversing"}:
        probes = [probe for probe in probes if probe.inspected]
    if not probes:
        return None
    selected = min(
        probes,
        key=lambda probe: (
            -_primary_source_score(normalized_category, probe),
            probe.source.path.casefold(),
            probe.source.path,
        ),
    )
    return selected.source


def _verify_rev_source_snapshot_tree(
    snapshot_root: Path,
    locator: str,
    *,
    expected_sha256: str,
    expected_size: int,
    maximum_bytes: int,
) -> ImmutableFile:
    """Verify the complete, single-file Rev snapshot topology."""

    normalized = normalize_locator(locator)
    if (
        not isinstance(expected_sha256, str)
        or len(expected_sha256) != 64
        or expected_sha256 != expected_sha256.lower()
        or any(
            character not in "0123456789abcdef"
            for character in expected_sha256
        )
        or isinstance(expected_size, bool)
        or not isinstance(expected_size, int)
        or expected_size < 0
        or expected_size > maximum_bytes
    ):
        raise SafeFileError("immutable snapshot binding is invalid")
    directory_flags = os.O_RDONLY | os.O_CLOEXEC
    directory_flags |= getattr(os, "O_DIRECTORY", 0)
    directory_flags |= getattr(os, "O_NOFOLLOW", 0)
    file_flags = os.O_RDONLY | os.O_CLOEXEC | os.O_NONBLOCK
    file_flags |= getattr(os, "O_NOFOLLOW", 0)
    descriptors: list[int] = []
    try:
        directory_descriptor = os.open(snapshot_root, directory_flags)
        descriptors.append(directory_descriptor)
        root_metadata = os.fstat(directory_descriptor)
        if (
            not stat.S_ISDIR(root_metadata.st_mode)
            or stat.S_IMODE(root_metadata.st_mode)
            != _REV_SOURCE_SNAPSHOT_DIRECTORY_MODE
            or os.listdir(directory_descriptor) != ["challenge"]
        ):
            raise SafeFileError(
                "immutable snapshot root topology is invalid"
            )
        directory_descriptor = os.open(
            "challenge",
            directory_flags,
            dir_fd=directory_descriptor,
        )
        descriptors.append(directory_descriptor)
        challenge_metadata = os.fstat(directory_descriptor)
        if (
            not stat.S_ISDIR(challenge_metadata.st_mode)
            or stat.S_IMODE(challenge_metadata.st_mode)
            != _REV_SOURCE_SNAPSHOT_DIRECTORY_MODE
        ):
            raise SafeFileError(
                "immutable snapshot challenge directory is invalid"
            )
        parts = normalized.split("/")
        for component in parts[:-1]:
            if os.listdir(directory_descriptor) != [component]:
                raise SafeFileError(
                    "immutable snapshot ancestor topology is invalid"
                )
            directory_descriptor = os.open(
                component,
                directory_flags,
                dir_fd=directory_descriptor,
            )
            descriptors.append(directory_descriptor)
            ancestor = os.fstat(directory_descriptor)
            if (
                not stat.S_ISDIR(ancestor.st_mode)
                or stat.S_IMODE(ancestor.st_mode)
                != _REV_SOURCE_SNAPSHOT_DIRECTORY_MODE
            ):
                raise SafeFileError(
                    "immutable snapshot ancestor is invalid"
                )
        if os.listdir(directory_descriptor) != [parts[-1]]:
            raise SafeFileError(
                "immutable snapshot leaf topology is invalid"
            )
        file_descriptor = os.open(
            parts[-1],
            file_flags,
            dir_fd=directory_descriptor,
        )
        descriptors.append(file_descriptor)
        before = os.fstat(file_descriptor)
        if (
            not stat.S_ISREG(before.st_mode)
            or stat.S_IMODE(before.st_mode)
            != _REV_SOURCE_SNAPSHOT_FILE_MODE
            or before.st_nlink != 1
            or before.st_size != expected_size
            or before.st_size > maximum_bytes
        ):
            raise SafeFileError(
                "immutable snapshot metadata does not match its binding"
            )
        digest = hashlib.sha256()
        total = 0
        while total <= maximum_bytes:
            block = os.read(
                file_descriptor,
                min(1024 * 1024, maximum_bytes + 1 - total),
            )
            if not block:
                break
            digest.update(block)
            total += len(block)
        after = os.fstat(file_descriptor)
        stable_fields = (
            "st_dev",
            "st_ino",
            "st_mode",
            "st_nlink",
            "st_size",
            "st_mtime_ns",
            "st_ctime_ns",
        )
        if (
            total != expected_size
            or digest.hexdigest() != expected_sha256
            or any(
                getattr(after, field) != getattr(before, field)
                for field in stable_fields
            )
        ):
            raise SafeFileError(
                "immutable snapshot bytes do not match their binding"
            )
    except OSError as error:
        raise SafeFileError(
            "immutable snapshot cannot be inspected safely"
        ) from error
    finally:
        for descriptor in reversed(descriptors):
            try:
                os.close(descriptor)
            except OSError:
                pass
    return ImmutableFile(
        path=snapshot_root / "challenge" / normalized,
        source_locator=normalized,
        sha256=expected_sha256,
        size_bytes=expected_size,
    )


def _run_id(prefix: str) -> str:
    stamp = time.strftime("%Y%m%d-%H%M%S", time.gmtime())
    safe = re.sub(r"[^A-Za-z0-9_.-]+", "-", prefix).strip("-") or "run"
    return f"{stamp}-{safe}-{uuid.uuid4().hex[:8]}"


def _durable_unlink(path: Path) -> None:
    """Remove one exact engine-owned file and persist the directory entry."""

    try:
        os.unlink(path)
    except FileNotFoundError:
        return
    flags = os.O_RDONLY | os.O_CLOEXEC
    flags |= getattr(os, "O_DIRECTORY", 0)
    descriptor = os.open(path.parent, flags)
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


def _durable_rmdir(path: Path) -> None:
    """Remove one exact engine-owned directory and persist its parent."""

    try:
        os.rmdir(path)
    except FileNotFoundError:
        return
    flags = os.O_RDONLY | os.O_CLOEXEC
    flags |= getattr(os, "O_DIRECTORY", 0)
    descriptor = os.open(path.parent, flags)
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


def _durable_unlink_beneath(
    root: Path,
    relative: PurePosixPath,
) -> None:
    """Unlink one relative leaf without following any ancestor symlink."""

    if (
        relative.is_absolute()
        or not relative.parts
        or any(part in {"", ".", ".."} for part in relative.parts)
    ):
        raise OSError("unsafe relative cleanup path")
    directory_flags = os.O_RDONLY | os.O_CLOEXEC
    directory_flags |= getattr(os, "O_DIRECTORY", 0)
    directory_flags |= getattr(os, "O_NOFOLLOW", 0)
    descriptors: list[int] = []
    try:
        current = os.open(root, directory_flags)
        descriptors.append(current)
        for component in relative.parts[:-1]:
            current = os.open(
                component,
                directory_flags,
                dir_fd=current,
            )
            descriptors.append(current)
        try:
            os.unlink(relative.parts[-1], dir_fd=current)
        except FileNotFoundError:
            return
        os.fsync(current)
    finally:
        for descriptor in reversed(descriptors):
            try:
                os.close(descriptor)
            except OSError:
                pass


def _durable_remove_pwn_run_directory(
    runs_root: Path,
    run_id: str,
) -> None:
    """Remove one exact fixed-topology Pwn run without following links."""

    if re.fullmatch(r"[A-Za-z0-9_.-]{1,255}", run_id) is None:
        raise OSError("unsafe Pwn run id")
    directory_flags = os.O_RDONLY | os.O_CLOEXEC
    directory_flags |= getattr(os, "O_DIRECTORY", 0)
    directory_flags |= getattr(os, "O_NOFOLLOW", 0)
    runs_descriptor: int | None = None
    run_descriptor: int | None = None
    raw_descriptor: int | None = None
    try:
        runs_descriptor = os.open(runs_root, directory_flags)
        try:
            before = os.stat(
                run_id,
                dir_fd=runs_descriptor,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            return
        if not stat.S_ISDIR(before.st_mode):
            raise OSError("Pwn run cleanup target is not a directory")
        run_descriptor = os.open(
            run_id,
            directory_flags,
            dir_fd=runs_descriptor,
        )
        opened = os.fstat(run_descriptor)
        if (
            not stat.S_ISDIR(opened.st_mode)
            or (opened.st_dev, opened.st_ino)
            != (before.st_dev, before.st_ino)
        ):
            raise OSError("Pwn run cleanup target changed while opening")
        allowed = {"raw", "request.json", "result.json", "validation.json"}
        unexpected = set(os.listdir(run_descriptor)) - allowed
        if unexpected:
            raise OSError(
                "Pwn run cleanup target contains unexpected entries"
            )
        for name in ("validation.json", "result.json", "request.json"):
            try:
                metadata = os.stat(
                    name,
                    dir_fd=run_descriptor,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                continue
            if not stat.S_ISREG(metadata.st_mode):
                raise OSError(
                    f"Pwn run cleanup leaf is not regular: {name}"
                )
            os.unlink(name, dir_fd=run_descriptor)
        try:
            raw_before = os.stat(
                "raw",
                dir_fd=run_descriptor,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            raw_before = None
        if raw_before is not None:
            if not stat.S_ISDIR(raw_before.st_mode):
                raise OSError(
                    "Pwn run cleanup raw target is not a directory"
                )
            raw_descriptor = os.open(
                "raw",
                directory_flags,
                dir_fd=run_descriptor,
            )
            raw_opened = os.fstat(raw_descriptor)
            if (
                (raw_opened.st_dev, raw_opened.st_ino)
                != (raw_before.st_dev, raw_before.st_ino)
                or os.listdir(raw_descriptor)
            ):
                raise OSError(
                    "Pwn run cleanup raw directory changed or is not empty"
                )
            os.close(raw_descriptor)
            raw_descriptor = None
            os.rmdir("raw", dir_fd=run_descriptor)
        if os.listdir(run_descriptor):
            raise OSError(
                "Pwn run cleanup target is not empty after exact cleanup"
            )
        os.fsync(run_descriptor)
        after = os.stat(
            run_id,
            dir_fd=runs_descriptor,
            follow_symlinks=False,
        )
        if (
            not stat.S_ISDIR(after.st_mode)
            or (after.st_dev, after.st_ino)
            != (before.st_dev, before.st_ino)
        ):
            raise OSError("Pwn run cleanup target changed before removal")
        os.close(run_descriptor)
        run_descriptor = None
        os.rmdir(run_id, dir_fd=runs_descriptor)
        os.fsync(runs_descriptor)
    finally:
        for descriptor in (
            raw_descriptor,
            run_descriptor,
            runs_descriptor,
        ):
            if descriptor is not None:
                try:
                    os.close(descriptor)
                except OSError:
                    pass


def _record_id(kind: str, run_id: str, local: str) -> str:
    normalized = re.sub(r"[^A-Za-z0-9_.:-]+", "-", local).strip("-")
    return f"{kind}-{run_id}-{normalized or uuid.uuid4().hex[:8]}"


def _managed_shell_argv(script: str) -> tuple[str, str, str]:
    """Bind one exact model-authored POSIX script to the sandbox shell."""

    if not isinstance(script, str) or not script.strip():
        raise ValueError("managed shell script cannot be empty")
    argv = (*MANAGED_SHELL_ARGV_PREFIX, script)
    CommandSpec.create(argv)
    return argv


